deploy.startCommand:
timeout --signal=TERM --kill-after=10s 180s python -B -u -c 'import hashlib,json,pathlib,subprocess,sys
r=subprocess.run([sys.executable,"-B","-u","-m","research.native_operational_20261017.probe","--authorized-research-only"],capture_output=True,text=True)
print(r.stdout,end="",flush=True)
if r.stderr:
 print("BTC15_PROBE_STDERR_BYTES "+str(len(r.stderr.encode())),flush=True)
for line in r.stdout.splitlines():
 try: summary=json.loads(line)
 except json.JSONDecodeError: continue
 if not isinstance(summary,dict) or "receipt" not in summary: continue
 p=pathlib.Path(summary["receipt"])
 if p.parent!=pathlib.Path("/research-evidence") or not p.name.startswith("native-operational-") or p.suffix!=".json" or p.is_symlink() or p.stat().st_size>131072: raise SystemExit("RECEIPT_PATH_OR_BOUND")
 blob=p.read_bytes()
 if hashlib.sha256(blob).hexdigest()!=summary["sha256"]: raise SystemExit("RECEIPT_HASH_MISMATCH")
 print("BTC15_OPERATIONAL_RECEIPT "+json.dumps(json.loads(blob),sort_keys=True,separators=(",",":")),flush=True)
sys.exit(r.returncode)
'
